-- BUGÜN: Karabük için kaynak bağlantılı sabit keşif noktaları.
-- Kayıtlar otomatik olarak doğrulanmış sayılmaz; yönetici incelemesinden önce needs_review durumunda kalır.
insert into public.places
  (name, category, city, address, latitude, longitude, slug,
   short_description, long_description, source_url, external_source, external_id,
   verified, trust_score, is_active, content_review_status)
select v.name, v.category, 'Karabük', v.address, v.latitude, v.longitude, v.slug,
       v.short_description, v.long_description, v.source_url, 'curated_seed',
       'karabuk-' || v.slug, false, 55, true, 'needs_review'
from (values
  ('Safranbolu Tarihi Çarşı ve Evleri','Tarih ve kültür','Çarşı, Çeşme Mahallesi, Safranbolu, Karabük',41.2490::float8,32.6940::float8,'safranbolu-tarihi-carsi-evleri','Geleneksel Osmanlı kent dokusu ve tarihî konutlarıyla tanınan miras alanı.','Safranbolu’nun tarihî çarşısı, geleneksel evleri ve sokak dokusu kentin kültürel mirasını birlikte görme imkânı sunar.','https://karabuk.ktb.gov.tr/TR-63751/gezilecek-yerler.html'),
  ('Cinci Hanı','Tarih','Eski Çarşı, Çeşme Mahallesi, Safranbolu, Karabük',41.2491::float8,32.6947::float8,'cinci-hani','17. yüzyılda yapılmış tarihî kervansaray.','1645 yılında yaptırılan Cinci Hanı, Safranbolu’nun tarihî ticaret merkezindeki önemli Osmanlı yapılarındandır.','https://www.kulturportali.gov.tr/turkiye/karabuk/gezilecekyer/cinci-hani'),
  ('İncekaya Su Kemeri','Tarih ve mimari','İncekaya, Safranbolu, Karabük',41.2670::float8,32.6800::float8,'incekaya-su-kemeri','Tokatlı Kanyonu üzerinde yer alan tarihî taş su kemeri.','Safranbolu’ya su ulaştırmak amacıyla yaptırılan İncekaya Su Kemeri, kanyon manzarasıyla birlikte görülebilen tarihî bir mühendislik yapısıdır.','https://www.kulturportali.gov.tr/turkiye/karabuk/gezilecekyer/ncekaya-su-kemeri'),
  ('Tokatlı Kanyonu','Doğa','Tokatlı, Safranbolu, Karabük',41.2670::float8,32.6800::float8,'tokatli-kanyonu','Yürüyüş rotası ve İncekaya Su Kemeri ile tanınan kanyon.','Tokatlı Kanyonu, aşınmayla oluşmuş vadisi, yürüyüş güzergâhı ve İncekaya Su Kemeri çevresindeki manzaralarıyla öne çıkar.','https://kulturportali.gov.tr/turkiye/karabuk/gezilecekyer/seyir-terasi'),
  ('Şeker Kanyonu','Doğa','Yenice yolu, Yenice, Karabük',41.1800::float8,32.3300::float8,'seker-kanyonu','Dik kaya duvarları ve doğa etkinlikleriyle bilinen kanyon.','Yenice yolu üzerindeki Şeker Kanyonu, yürüyüş ve doğa gözlemi için öne çıkan doğal alanlardan biridir; parkur koşulları önceden değerlendirilmelidir.','https://www.kulturportali.gov.tr/turkiye/karabuk/gezilecekyer/seker-kanyonu'),
  ('Bulak Mencilis Mağarası','Doğa','Bulak köyü, Safranbolu, Karabük',41.2800::float8,32.5900::float8,'bulak-mencilis-magarasi','Sarkıt, dikit ve yer altı oluşumlarıyla bilinen mağara.','Bulak Mencilis Mağarası, geniş yer altı oluşumlarıyla Karabük’ün dikkat çeken doğal miras noktalarındandır; ziyaret edilebilen bölüm ve saatler önceden kontrol edilmelidir.','https://karabuk.ktb.gov.tr/TR-63745/turizm.html'),
  ('Yörük Köyü','Tarih ve kültür','Yörük köyü, Safranbolu, Karabük',41.2850::float8,32.6500::float8,'yoruk-koyu','Geleneksel Safranbolu sivil mimarisini koruyan tarihî köy.','Yörük Köyü, geleneksel konutları ve tarihî köy dokusuyla bölgenin kırsal kültürünü tanımak için ziyaret edilen bir yerleşimdir.','https://karabuk.ktb.gov.tr/TR-63751/gezilecek-yerler.html'),
  ('Safranbolu Saat Kulesi','Tarih','Kale altı, Safranbolu, Karabük',41.2470::float8,32.6900::float8,'safranbolu-saat-kulesi','Safranbolu’nun tarihî kent siluetindeki saat kulesi.','Tarihî saat kulesi, Safranbolu’nun eski kent dokusu içinde görülebilecek kültürel yapılardan biridir.','https://karabuk.ktb.gov.tr/TR-63751/gezilecek-yerler.html'),
  ('Kaymakamlar Gezi Evi','Müze ve kültür','Çarşı, Safranbolu, Karabük',41.2480::float8,32.6930::float8,'kaymakamlar-gezi-evi','Geleneksel Safranbolu ev yaşamını tanıtan tarihî konut.','Kaymakamlar Gezi Evi, geleneksel konut mimarisini ve geçmişteki ev yaşamını anlamaya yardımcı olan kültürel duraklardan biridir.','https://karabuk.ktb.gov.tr/TR-63751/gezilecek-yerler.html'),
  ('Köprülü Mehmet Paşa Camii','Tarih ve mimari','Eski Çarşı, Safranbolu, Karabük',41.2488::float8,32.6952::float8,'koprulu-mehmet-pasa-camii','Safranbolu tarihî çarşısındaki önemli Osmanlı camisi.','Köprülü Mehmet Paşa Camii, avlusu ve çevresindeki tarihî çarşı dokusuyla Safranbolu kültür rotasının önemli duraklarındandır.','https://www.kulturportali.gov.tr/turkiye/karabuk'),
  ('Hıdırlık Tepesi','Manzara ve kültür','Hıdırlık, Safranbolu, Karabük',41.2450::float8,32.6860::float8,'hidirlik-tepesi-safranbolu','Tarihî Safranbolu evlerini yukarıdan izleme noktası.','Hıdırlık Tepesi, Safranbolu’nun geleneksel kent dokusunu ve çevresini seyretmek için tercih edilen manzara noktalarındandır.','https://karabuk.ktb.gov.tr/TR-63751/gezilecek-yerler.html'),
  ('Hadrianopolis Antik Kenti','Tarih ve arkeoloji','Budaklar köyü, Eskipazar, Karabük',40.9500::float8,32.5300::float8,'hadrianopolis-antik-kenti','Roma ve erken Bizans dönemleriyle ilişkilendirilen arkeolojik alan.','Eskipazar yakınındaki Hadrianopolis, kazı ve araştırmalarla tanınan antik yerleşimdir; ziyaret alanlarının güncel erişim durumu kontrol edilmelidir.','https://karabuk.ktb.gov.tr/TR-273546/karabuk-ili39nin-tarihi-ve-dogal-guzellikleri.html'),
  ('Yenice Ormanları','Doğa','Yenice ilçesi, Karabük',41.2000::float8,32.3500::float8,'yenice-ormanlari','Geniş orman ekosistemi ve doğa yürüyüşü rotalarıyla bilinen alan.','Yenice Ormanları, zengin orman dokusu ve doğa rotalarıyla Karabük’ün öne çıkan doğal alanlarındandır; hassas habitatlarda işaretli güzergâhlar izlenmelidir.','https://karabuk.ktb.gov.tr/TR-63745/turizm.html'),
  ('Sorkun Yaylası','Doğa','Karabük-Yenice-Eskipazar çevresi, Karabük',40.9800::float8,32.4200::float8,'sorkun-yaylasi','Yüksek rakımlı, yürüyüş için tercih edilen yayla alanı.','Sorkun Yaylası, ormanlık çevresi ve doğa yürüyüşü olanaklarıyla bilinir; mevsim ve yol koşulları ziyaret öncesinde kontrol edilmelidir.','https://karabuk.ktb.gov.tr/TR-63756/yaylalar.html'),
  ('Safranbolu Kent Tarihi Müzesi','Müze ve kültür','Kale, Safranbolu, Karabük',41.2460::float8,32.6900::float8,'safranbolu-kent-tarihi-muzesi','Safranbolu’nun kent geçmişini ve kültürel mirasını anlatan müze.','Kent Tarihi Müzesi, Safranbolu’nun tarihî gelişimini ve yerel kültürünü tanımak için yararlı bir kültür durağıdır.','https://karabuk.ktb.gov.tr/TR-63751/gezilecek-yerler.html')
) as v(name,category,address,latitude,longitude,slug,short_description,long_description,source_url)
where not exists (
  select 1 from public.places p
  where lower(trim(p.city)) = 'karabük'
    and lower(trim(p.name)) = lower(trim(v.name))
);
